type KeysWithUndefinedValues<T extends Record<string, unknown>> = {
    [K in keyof T]: undefined extends T[K] ? K : never;
}[keyof T];
type KeysWithoutUndefinedValues<T extends Record<string, unknown>> = Exclude<keyof T, KeysWithUndefinedValues<T>>;
export type OmitUndefinedValues<T extends Record<string, unknown>> = Pick<T, KeysWithoutUndefinedValues<T>> & Partial<{
    [K in KeysWithUndefinedValues<T>]: Exclude<T[K], undefined>;
}>;
export declare function omitUndefinedValues<T extends Record<string, unknown>>(value: T): OmitUndefinedValues<T>;
export {};
